<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Forms;

use Override;
use Psr\Http\Message\ResponseInterface;
use Civi\Lughauth\Features\Oidc\Authentication\Application\AuthenticateUser;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\Exception\LoginException;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\StepInput;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\StepName;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\StepResult;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Services\DecorateHtml;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Services\HtmlSecurer;
use Civi\Lughauth\Features\Oidc\WebAuthn\Domain\Gateway\WebAuthnChallengeGateway;
use Civi\Lughauth\Features\Access\Tenant\Domain\Gateway\TenantReadGateway;
use Civi\Lughauth\Shared\Infrastructure\Translation\MessageProvider;

final class WebAuthnLoginForm implements StepForm
{
    public function __construct(
        private readonly MessageProvider $messages,
        private readonly AuthenticateUser $authenticator,
        private readonly DecorateHtml $decorator,
        private readonly HtmlSecurer $securer,
        private readonly WebAuthnChallengeGateway $challengeGateway,
        private readonly TenantReadGateway $tenants,
    ) {
    }

    #[Override]
    public function render(StepInput $input, ResponseInterface $response, ?AuthenticationResult $error): StepResult
    {
        $locale = '';
        $tenant = $input->context->tenant;
        $step = StepName::WEBAUTHN_LOGIN->value;
        $backStep = StepName::LOGIN->value;

        $js = $this->securer->configureScripts([
            $this->securer->addSign('sign'),
        ]);

        $translator = $this->messages->messages('forms', $locale, __DIR__ . '/../../Translations');
        $title = $translator->get('webauthn.title');
        $help = $translator->get('webauthn.help');
        $buttonLabel = $translator->get('webauthn.authenticate');
        $backText = $translator->get('webauthn.back-text', [
            '<input class="inline" type="submit" value="' . $translator->get('webauthn.back-label') . '" />',
        ]);

        $errorCode = $error?->error;
        $errorHtml = $errorCode !== null && $errorCode !== ''
            ? '<p class="error">' . $translator->get('webauthn.error-format', [$translator->get('error.' . strtolower($errorCode))]) . '</p>'
            : '';

        $authenticateBeginPath = "/oauth/openid/{$tenant}/webauthn/authenticate/begin";
        $authenticateFinishPath = "/oauth/openid/{$tenant}/webauthn/authenticate/finish";

        $webAuthnScript = <<<JS
            <script>
            (function() {
                function b64url(bytes) {
                    return btoa(String.fromCharCode(...new Uint8Array(bytes)))
                        .replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');
                }
                function fromB64url(str) {
                    str = str.replace(/-/g, '+').replace(/_/g, '/');
                    while (str.length % 4) str += '=';
                    return Uint8Array.from(atob(str), c => c.charCodeAt(0));
                }

                document.getElementById('webauthn-btn').addEventListener('click', async function() {
                    const statusEl = document.getElementById('webauthn-status');
                    statusEl.textContent = '';
                    try {
                        const beginRes = await fetch('{$authenticateBeginPath}', {method: 'POST', headers: {'Content-Type': 'application/json'}, body: '{}'});
                        const options = await beginRes.json();

                        const publicKey = {
                            challenge: fromB64url(options.challenge),
                            timeout: options.timeout || 60000,
                            rpId: options.rpId,
                            userVerification: options.userVerification || 'preferred',
                        };

                        const credential = await navigator.credentials.get({publicKey});

                        const credPayload = {
                            id: credential.id,
                            rawId: b64url(credential.rawId),
                            type: credential.type,
                            response: {
                                clientDataJSON: b64url(credential.response.clientDataJSON),
                                authenticatorData: b64url(credential.response.authenticatorData),
                                signature: b64url(credential.response.signature),
                                userHandle: credential.response.userHandle ? b64url(credential.response.userHandle) : null,
                            },
                        };

                        const finishRes = await fetch('{$authenticateFinishPath}', {
                            method: 'POST',
                            headers: {'Content-Type': 'application/json'},
                            body: JSON.stringify({challengeId: options.challengeId, credential: credPayload}),
                        });
                        const finishData = await finishRes.json();

                        if (finishData.status === 'ok') {
                            document.getElementById('webauthn-challenge-id').value = finishData.challengeId;
                            document.getElementById('webauthn-form').submit();
                        } else {
                            statusEl.textContent = 'Authentication failed';
                        }
                    } catch (err) {
                        statusEl.textContent = err.message || 'WebAuthn error';
                    }
                });
            })();
            </script>
            JS;

        $response->getBody()->write($this->decorator->getFullPage(
            $input->request,
            'WebAuthn Login',
            $js . <<<HTML
                <h1>{$title}</h1>
                <p>{$help}</p>
                {$errorHtml}
                <p id="webauthn-status" class="error"></p>
                <button type="button" id="webauthn-btn" class="primary-button">{$buttonLabel}</button>
                <form method="POST" id="webauthn-form" style="display:none">
                    <input type="hidden" name="csid" id="sign" />
                    <input type="hidden" name="step" value="{$step}" />
                    <input type="hidden" name="webauthn_challenge_id" id="webauthn-challenge-id" value="" />
                </form>
                <form method="POST">
                    <input type="hidden" name="step" value="{$backStep}" />
                    {$backText}
                </form>
                {$webAuthnScript}
            HTML,
            $locale
        ));

        return StepResult::render($response, $input->challenges);
    }

    #[Override]
    public function authenticate(StepInput $input): StepResult
    {
        $csid = (string) ($input->body['csid'] ?? '');
        $challengeId = (string) ($input->body['webauthn_challenge_id'] ?? '');

        $tenant = $input->context->tenant;
        $tenantObj = $this->tenants->findOneByName($tenant);
        $tenantId = $tenantObj?->uid() ?? $tenant;

        $challenge = $this->challengeGateway->findById($challengeId, $tenantId);

        if (!$challenge || !$challenge->verified || $challenge->verifiedUsername === null) {
            throw new LoginException(
                auth: AuthenticationResult::wrongCredentials($tenant, ''),
                message: 'WebAuthn challenge not verified',
                challenges: $input->challenges
            );
        }

        if ($challenge->isExpired()) {
            throw new LoginException(
                auth: AuthenticationResult::wrongCredentials($tenant, ''),
                message: 'WebAuthn challenge expired',
                challenges: $input->challenges
            );
        }

        $updated = $input->challenges->withUsername($challenge->verifiedUsername);
        $auth = $this->authenticator->preAuthenticate(
            $input->authRequest,
            $updated,
            $tenant,
            $input->context->issuer,
            $csid,
            $input->context->state,
            $input->context->nonce,
        );

        return StepResult::proceed($auth, $updated);
    }
}
